@app.post("/webhook/telegram")
async def telegram_webhook(update: TelegramUpdate,
                           background: BackgroundTasks):
    # 1 · validate (platform signature — reject forgeries fast)
    if not verify_signature(raw_body, headers):
        raise HTTPException(403)

    msg = update.message
    if not msg or msg.from_user.is_bot:
        return {"ok": True}              # ignore bots, edits, services

    # 2 · idempotent enqueue — platforms REDELIVER on timeout
    job_id = f"tg-{msg.message_id}"      # natural dedupe key
    if seen(job_id):
        return {"ok": True}

    queue.push(job_id, {
        "chat_id": msg.chat.id,
        "user_id": msg.from_user.id,
        "text": msg.text,
        "placeholder": telegram.send(msg.chat.id, "…"),
    })
    return {"ok": True}                  # 200 in ms; work happens async
